/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-upload-fg | --an-upload-bg | --an-upload-border-color | --an-upload-radius
   | --an-upload-gap | --an-upload-font-size | --an-upload-focus-ring
   | --an-upload-dropzone-padding | --an-upload-dropzone-gap | --an-upload-dragover-border-color
   | --an-upload-trigger-height | --an-upload-trigger-padding-x | --an-upload-trigger-radius
   | --an-upload-trigger-bg | --an-upload-trigger-fg | --an-upload-trigger-font-size
   | --an-upload-hint-color | --an-upload-hint-font-size
   | --an-upload-list-gap | --an-upload-item-bg | --an-upload-item-border-color
   | --an-upload-item-radius | --an-upload-item-padding | --an-upload-item-gap
   | --an-upload-preview-size | --an-upload-preview-radius | --an-upload-preview-bg
   | --an-upload-name-font-size | --an-upload-size-color | --an-upload-size-font-size
   | --an-upload-progress-height | --an-upload-progress-color | --an-upload-progress-track
   | --an-upload-error-color | --an-upload-error-font-size
   | --an-upload-button-bg | --an-upload-button-color | --an-upload-button-border-color
   | --an-upload-button-radius | --an-upload-button-font-size | --an-upload-empty-color.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: block;
  box-sizing: border-box;
  color-scheme: light dark;
  color: var(--an-upload-fg, var(--an-color-fg-1, #18181b));
  font-family: inherit;
  font-size: var(--an-upload-font-size, var(--an-font-size-md, 1rem));
  line-height: 1.5;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

:host([hidden]) {
  display: none;
}

.base {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--an-upload-gap, var(--an-space-3, 0.75rem));
  width: 100%;
}

/* The picker: whole surface clicks, keyboard-activatable, drop target. */
.dropzone {
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--an-upload-dropzone-gap, var(--an-space-2, 0.5rem) var(--an-space-3, 0.75rem));
  width: 100%;
  padding: var(--an-upload-dropzone-padding, var(--an-space-6, 1.5rem) var(--an-space-4, 1rem));
  border: 1px dashed var(--an-upload-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-upload-radius, var(--an-radius-lg, 0.75rem));
  background-color: var(--an-upload-bg, var(--an-color-bg-1, #ffffff));
  color: inherit;
  text-align: center;
  cursor: pointer;
  transition: border-color 120ms ease, outline-color 120ms ease;
}

.dropzone:hover {
  border-color: var(--an-upload-dragover-border-color, var(--an-color-accent-9, #2563eb));
}

.dropzone[data-dragover] {
  border-color: var(--an-upload-dragover-border-color, var(--an-color-accent-9, #2563eb));
  outline: 1px solid var(--an-upload-dragover-border-color, var(--an-color-accent-9, #2563eb));
  outline-offset: -2px;
}

.dropzone[aria-disabled='true'] {
  cursor: not-allowed;
  opacity: 0.55;
}

.dropzone:focus-visible {
  outline: 2px solid var(--an-upload-focus-ring, var(--an-color-accent-9, #2563eb));
  outline-offset: 2px;
}

.input {
  display: none;
}

.trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--an-upload-trigger-height, 2rem);
  padding: 0 var(--an-upload-trigger-padding-x, var(--an-space-3, 0.75rem));
  border-radius: var(--an-upload-trigger-radius, var(--an-radius-md, 0.5rem));
  background-color: var(--an-upload-trigger-bg, var(--an-color-accent-9, #2563eb));
  color: var(--an-upload-trigger-fg, #ffffff);
  font-size: var(--an-upload-trigger-font-size, var(--an-font-size-sm, 0.875rem));
  font-weight: 600;
}

.hint {
  color: var(--an-upload-hint-color, var(--an-color-fg-1, #18181b));
  font-size: var(--an-upload-hint-font-size, var(--an-font-size-sm, 0.875rem));
  opacity: 0.72;
}

.list {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--an-upload-list-gap, var(--an-space-2, 0.5rem));
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--an-upload-item-gap, var(--an-space-3, 0.75rem));
  padding: var(--an-upload-item-padding, var(--an-space-2, 0.5rem) var(--an-space-3, 0.75rem));
  border: 1px solid var(--an-upload-item-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-upload-item-radius, var(--an-radius-md, 0.5rem));
  background-color: var(--an-upload-item-bg, var(--an-color-bg-1, #ffffff));
}

.item-preview {
  box-sizing: border-box;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--an-upload-preview-size, 2.5rem);
  height: var(--an-upload-preview-size, 2.5rem);
  overflow: hidden;
  border-radius: var(--an-upload-preview-radius, var(--an-radius-sm, 0.25rem));
  background-color: var(--an-upload-preview-bg, var(--an-color-border-1, #d4d4d8));
  color: var(--an-upload-hint-color, var(--an-color-fg-1, #18181b));
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.item-preview img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.item-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.item-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--an-upload-item-gap, var(--an-space-3, 0.75rem));
  min-width: 0;
}

.item-name {
  overflow: hidden;
  font-size: var(--an-upload-name-font-size, var(--an-font-size-sm, 0.875rem));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item-size {
  flex: none;
  color: var(--an-upload-size-color, var(--an-color-fg-1, #18181b));
  font-size: var(--an-upload-size-font-size, var(--an-font-size-xs, 0.75rem));
  font-variant-numeric: tabular-nums;
  opacity: 0.6;
}

.item-progress {
  display: block;
  height: var(--an-upload-progress-height, 0.375rem);
  overflow: hidden;
  border-radius: var(--an-radius-full, 999px);
  background-color: var(--an-upload-progress-track, var(--an-color-border-1, #d4d4d8));
}

.item-progress > .bar {
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  background-color: var(--an-upload-progress-color, var(--an-color-accent-9, #2563eb));
  transition: width 120ms ease;
}

.item[data-status='success'] .item-progress > .bar {
  background-color: var(--an-upload-progress-color, var(--an-color-accent-9, #2563eb));
}

.item[data-status='error'] .item-progress > .bar {
  background-color: var(--an-upload-error-color, var(--an-color-danger-9, #dc2626));
}

.item-error {
  color: var(--an-upload-error-color, var(--an-color-danger-9, #dc2626));
  font-size: var(--an-upload-error-font-size, var(--an-font-size-xs, 0.75rem));
}

.item-actions {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--an-space-1, 0.25rem);
}

.item-remove,
.item-cancel {
  padding: 0.125rem 0.5rem;
  border: 1px solid var(--an-upload-button-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-upload-button-radius, var(--an-radius-sm, 0.25rem));
  background-color: var(--an-upload-button-bg, transparent);
  color: var(--an-upload-button-color, var(--an-color-accent-9, #2563eb));
  font: inherit;
  font-size: var(--an-upload-button-font-size, var(--an-font-size-xs, 0.75rem));
  cursor: pointer;
}

.item-remove:hover,
.item-cancel:hover {
  border-color: var(--an-upload-button-color, var(--an-color-accent-9, #2563eb));
}

.item-remove:focus-visible,
.item-cancel:focus-visible {
  outline: 2px solid var(--an-upload-focus-ring, var(--an-color-accent-9, #2563eb));
  outline-offset: 1px;
}

.empty {
  margin: 0;
  color: var(--an-upload-empty-color, var(--an-color-fg-1, #18181b));
  font-size: var(--an-upload-hint-font-size, var(--an-font-size-sm, 0.875rem));
  text-align: center;
  opacity: 0.6;
}

:host([size='sm']) .dropzone {
  padding: var(--an-upload-dropzone-padding, var(--an-space-4, 1rem));
}

:host([size='md']) .dropzone {
  padding: var(--an-upload-dropzone-padding, var(--an-space-6, 1.5rem) var(--an-space-4, 1rem));
}

:host([size='lg']) .dropzone {
  padding: var(--an-upload-dropzone-padding, var(--an-space-8, 2rem) var(--an-space-5, 1.25rem));
}

:host([size='sm']) .trigger {
  min-height: var(--an-upload-trigger-height, 1.75rem);
  font-size: var(--an-upload-trigger-font-size, var(--an-font-size-xs, 0.75rem));
}

:host([size='lg']) .trigger {
  min-height: var(--an-upload-trigger-height, 2.5rem);
  font-size: var(--an-upload-trigger-font-size, var(--an-font-size-md, 1rem));
}

@media (prefers-reduced-motion: reduce) {
  .dropzone,
  .item-progress > .bar {
    transition: none;
  }
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** Defaults for list properties; an attribute holds the items comma-separated. */
export type ArrayDefaults = Record<string, string[]>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/** `"a, b"` -> `['a', 'b']`; an absent attribute restores the fallback list. */
function toList(value: string | null, fallback: readonly string[]): string[] {
  if (value === null) return [...fallback];
  return value
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** Order-sensitive comparison, used to skip redundant writes and renders. */
function sameList(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((part, index) => part === b[index]);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 * - `static arrayDefaults` opts an attribute into a comma-separated `string[]`
 *   property. Elements that do not declare it keep a scalar-only API.
 * - `checkValidity()` / `reportValidity()` / `reset()` / `getFormData()` wrap the
 *   platform form surface so a subclass does not repeat it.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /**
   * Array-backed properties and their defaults. The attribute holds the items
   * comma-separated (`items="a, b"`); the property is a `string[]`.
   */
  static arrayDefaults: ArrayDefaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return [
      ...Object.keys(this.defaults).map(toKebabCase),
      ...Object.keys(this.arrayDefaults).map(toKebabCase),
    ];
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #arrayDefaults: ArrayDefaults = {};
  #arrays: Record<string, string[]> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#arrayDefaults = ctor.arrayDefaults;
    this.#arrays = {};
    for (const key of Object.keys(ctor.arrayDefaults)) {
      this.#arrays[key] = [...ctor.arrayDefaults[key]];
    }
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }

    for (const key of Object.keys(ctor.arrayDefaults)) {
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => [...(this.#arrays[key] ?? [])],
        set: (next: string[] | string) => this.#assignList(key, next),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /**
   * Constraint validation in the owning form. Forwards to `ElementInternals`
   * when available; without internals there is nothing to validate, so it
   * reports `true`.
   */
  checkValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.checkValidity !== 'function') return true;
    return internals.checkValidity();
  }

  /** Like `checkValidity()`, but asks the platform to report the problem. */
  reportValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.reportValidity !== 'function') return true;
    return internals.reportValidity();
  }

  /**
   * Resets the control to the state it was mounted with and re-renders.
   * Delegates to `formResetCallback()` so a subclass only overrides
   * `onFormReset()`.
   */
  reset(): void {
    this.formResetCallback();
    this.requestUpdate();
  }

  /**
   * Serializes this element the way `new FormData(form)` would: one row per
   * `formEntries()` entry, or `null` when the element submits nothing.
   */
  getFormData(): FormData | null {
    const entries = this.formEntries();
    if (entries.length === 0) return null;
    const data = new FormData();
    for (const [name, value] of entries) data.append(name, value);
    return data;
  }

  /**
   * Rows this element contributes to `FormData`. Defaults to `name` + `value`
   * when both are usable; subclasses with a richer payload override it.
   */
  protected formEntries(): Array<[string, string | File]> {
    const { name, value } = this as unknown as { name?: unknown; value?: unknown };
    if (typeof name !== 'string' || name.length === 0) return [];
    if (typeof value !== 'string' && typeof value !== 'number') return [];
    return [[name, String(value)]];
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (key in this.#arrayDefaults) {
      this.#arrays[key] = toList(value, this.#arrayDefaults[key]); // attribute -> list property
      if (this.#rendered && !this.#reflecting) this.requestUpdate();
      return;
    }
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assignList(key: string, next: string[] | string): void {
    const value = Array.isArray(next)
      ? next.map((part) => String(part).trim()).filter((part) => part.length > 0)
      : toList(next, []);
    if (sameList(this.#arrays[key] ?? [], value)) return;
    this.#arrays[key] = value;
    this.#reflectList(key, value);
  }

  #reflectList(key: string, value: string[]): void {
    const attribute = toKebabCase(key);
    const fallback = this.#arrayDefaults[key] ?? [];
    this.#reflecting = true;
    try {
      if (value.length === 0 || sameList(value, fallback)) this.removeAttribute(attribute);
      else this.setAttribute(attribute, value.join(','));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

import type { AnUploader } from './an-upload';

/** Options accepted by `createXhrUploader`. */
export interface XhrUploaderOptions {
  /** Endpoint that receives the multipart body. */
  url: string;
  /** HTTP method; defaults to `POST`. */
  method?: string;
  /** Extra request headers sent with the request. */
  headers?: Record<string, string>;
  /** Multipart field that carries the file; defaults to `file`. */
  fieldName?: string;
}

/** `AbortError`-shaped rejection; `DOMException` is not available everywhere. */
function abortError(): Error {
  const error = new Error('上传已取消');
  error.name = 'AbortError';
  return error;
}

/** JSON when the response body parses as JSON, the raw text otherwise. */
function parseResponse(xhr: XMLHttpRequest): unknown {
  const text = typeof xhr.responseText === 'string' ? xhr.responseText : '';
  if (text.length === 0) return null;
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

/**
 * Builds the default `uploader` transport on top of `XMLHttpRequest`.
 *
 * `XMLHttpRequest` is used instead of `fetch` on purpose: only XHR exposes
 * `upload.onprogress`, which the progress bar and `an-upload-progress` need.
 * The returned function sends one file per request as `multipart/form-data`,
 * resolves with the parsed response body for a 2xx status and rejects for
 * everything else. Aborting `context.signal` cancels the request and rejects
 * with an `AbortError`.
 *
 * @param options - Endpoint, HTTP method, headers and multipart field name.
 * @returns An `AnUploader` usable as the `uploader` property or standalone.
 */
export function createXhrUploader(options: XhrUploaderOptions): AnUploader {
  const url = options.url;
  const method = options.method || 'POST';
  const fieldName = options.fieldName || 'file';
  const headers = options.headers ?? {};

  return (file, context) =>
    new Promise<unknown>((resolve, reject) => {
      if (context.signal.aborted) {
        reject(abortError());
        return;
      }

      const xhr = new XMLHttpRequest();
      let settled = false;

      const cleanup = (): void => {
        context.signal.removeEventListener('abort', onAbort);
      };
      const settle = (action: () => void): void => {
        if (settled) return;
        settled = true;
        cleanup();
        action();
      };
      const onAbort = (): void => {
        // `abort()` synchronously fires `onabort`; settle() keeps the outcome
        // single even when the platform also reports a load/error afterwards.
        try {
          xhr.abort();
        } catch {
          // The request may already have finished; the rejection below wins.
        }
        settle(() => reject(abortError()));
      };

      context.signal.addEventListener('abort', onAbort, { once: true });

      xhr.open(method, url, true);
      for (const [name, value] of Object.entries(headers)) {
        xhr.setRequestHeader(name, value);
      }

      xhr.upload.onprogress = (event: ProgressEvent): void => {
        if (settled) return;
        const total = event.total > 0 ? event.total : file.size;
        context.onProgress(event.loaded, total);
      };

      xhr.onload = (): void => {
        settle(() => {
          if (xhr.status >= 200 && xhr.status < 300) resolve(parseResponse(xhr));
          else reject(new Error(`上传失败（HTTP ${xhr.status}）`));
        });
      };

      xhr.onerror = (): void => {
        settle(() => reject(new Error('上传失败：网络错误')));
      };

      xhr.onabort = (): void => {
        settle(() => reject(abortError()));
      };

      const body = new FormData();
      body.append(fieldName, file);
      xhr.send(body);
    });
}

import uploadStyles from './an-upload.css?inline';
import { AnElement } from '../internal/base';
import { createXhrUploader } from './xhr-uploader';

/** Sizes of `<an-upload>` and its dropzone. */
export type AnUploadSize = 'sm' | 'md' | 'lg';

/** Why the component refused a file. */
export type AnUploadRejectReason = 'size' | 'type' | 'max-files';

/** Lifecycle of one queued file. */
export type AnUploadStatus = 'idle' | 'uploading' | 'success' | 'error' | 'aborted';

/** Context handed to a custom `uploader`. */
export interface AnUploadContext {
  /** Aborted by `abort()`, `remove()` or `clear()` while the transfer runs. */
  signal: AbortSignal;
  /** Reports bytes transferred so the row can render a progress bar. */
  onProgress: (loaded: number, total: number) => void;
}

/** Transport that pushes one file; `createXhrUploader` builds the default one. */
export type AnUploader = (file: File, context: AnUploadContext) => Promise<unknown>;

/** Payload of `an-upload-change`. */
export interface AnUploadChangeDetail {
  /** Every file currently queued, in display order. */
  files: File[];
  /** Files added by this change. */
  added: File[];
  /** Files removed by this change. */
  removed: File[];
}

/** Payload of `an-upload-reject`. */
export interface AnUploadRejectDetail {
  /** The file that was refused. */
  file: File;
  /** Which rule refused it. */
  reason: AnUploadRejectReason;
}

/** Payload of `an-upload-progress`. */
export interface AnUploadProgressDetail {
  /** The file being transferred. */
  file: File;
  /** Bytes transferred so far. */
  loaded: number;
  /** Total bytes expected. */
  total: number;
  /** `loaded / total` as a whole percentage, clamped to 0..100. */
  percent: number;
}

/** Payload of `an-upload-success`. */
export interface AnUploadSuccessDetail {
  /** The file that finished. */
  file: File;
  /** Whatever the uploader resolved with (the parsed response by default). */
  response: unknown;
}

/** Payload of `an-upload-error`. */
export interface AnUploadErrorDetail {
  /** The file that failed. */
  file: File;
  /** The rejection value from the uploader. */
  error: unknown;
}

/** Payload of `an-upload-abort`. */
export interface AnUploadAbortDetail {
  /** The file whose transfer was cancelled. */
  file: File;
}

/** One queued file plus the upload state that is not part of the public API. */
interface UploadItem {
  /** The selected file. */
  file: File;
  /** Current lifecycle state. */
  status: AnUploadStatus;
  /** Bytes transferred so far. */
  loaded: number;
  /** Total bytes expected. */
  total: number;
  /** Cached percentage, so a re-render never recomputes it. */
  percent: number;
  /** Value the uploader resolved with. */
  response?: unknown;
  /** Human-readable failure text. */
  error?: string;
  /** Object URL of the image thumbnail; `null` for non-images. */
  previewUrl: string | null;
  /** Controller of the in-flight request, if any. */
  controller?: AbortController;
}

/** Shown to the owning form when `required` is set and the queue is empty. */
const REQUIRED_MESSAGE = '此字段为必填项。';

/** Fallback multipart field when neither `field-name` nor `name` is set. */
const DEFAULT_FIELD_NAME = 'file';

/** Escapes text used inside an attribute value or element content. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/** `2048` -> `2 KB`; bytes below 1 KB keep the `B` unit. */
function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  if (bytes < 1024) return `${Math.round(bytes)} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${trimZero(kb)} KB`;
  return `${trimZero(kb / 1024)} MB`;
}

/** `2.0` -> `2`; keeps `1.5` as is. */
function trimZero(value: number): string {
  return value.toFixed(1).replace(/\.0$/, '');
}

/** A human-readable message for any rejection value. */
function messageOf(error: unknown): string {
  if (error instanceof Error && error.message) return error.message;
  if (typeof error === 'string' && error.length > 0) return error;
  return '上传失败';
}

/** Splits `accept` into normalised tokens; empty means "anything". */
function parseAccept(accept: string): string[] {
  return accept
    .split(',')
    .map((token) => token.trim().toLowerCase())
    .filter((token) => token.length > 0);
}

/**
 * `<an-upload>` — file picker, drop target and upload queue in one control.
 *
 * The component never sends anything unless `action` or the `uploader` property
 * provides a transport. Files are validated locally first (`accept`,
 * `max-size`, `max-files`), then queued and uploaded with a concurrency limit.
 * It is form associated: every accepted file is appended to `FormData` under
 * `field-name` (falling back to `name`).
 *
 * @attr name - Form field name and the default multipart field name.
 * @attr accept - Comma-separated MIME types, `image/*` wildcards or `.ext` names.
 * @attr multiple - Lets the picker and drop target accept more than one file.
 * @attr max-files - Upper bound of queued files; `0` means unlimited.
 * @attr max-size - Per-file upper bound in bytes; `0` means unlimited.
 * @attr disabled - Disables picking, dropping and uploading.
 * @attr required - Marks the control invalid while the queue is empty.
 * @attr action - Upload endpoint; enables the built-in XHR uploader.
 * @attr method - HTTP method for `action`; defaults to `POST`.
 * @attr field-name - Multipart field name; defaults to `name`.
 * @attr auto-upload - Starts uploading as soon as files are added; defaults to `true`.
 * @attr size - Control size: `sm`, `md` or `lg`.
 *
 * @fires an-upload-change - Files were added, removed or cleared; detail is `AnUploadChangeDetail`.
 * @fires an-upload-reject - A file failed validation; detail is `AnUploadRejectDetail`.
 * @fires an-upload-progress - Bytes were transferred; detail is `AnUploadProgressDetail`.
 * @fires an-upload-success - A file finished; detail is `AnUploadSuccessDetail`.
 * @fires an-upload-error - A file failed; detail is `AnUploadErrorDetail`.
 * @fires an-upload-abort - A running upload was cancelled; detail is `AnUploadAbortDetail`.
 *
 * @slot trigger - Replaces the default button and hint inside the dropzone.
 * @csspart base - Root wrapper.
 * @csspart dropzone - Clickable, keyboard-activatable drop area.
 * @csspart trigger - Default "choose file" button (absent when `trigger` is slotted).
 * @csspart list - `<ul>` that holds the queued files.
 * @csspart item - One `<li>` per queued file.
 * @csspart item-preview - Thumbnail slot of an item.
 * @csspart item-name - File name of an item.
 * @csspart item-size - Human-readable file size of an item.
 * @csspart item-progress - Progress bar track of an item.
 * @csspart item-error - Error text of an item.
 * @csspart item-remove - Remove button of an item.
 * @csspart item-cancel - Cancel button, rendered only while uploading.
 * @csspart empty - Placeholder shown while the queue is empty.
 * @cssproperty --an-upload-fg - Text colour.
 * @cssproperty --an-upload-bg - Dropzone background.
 * @cssproperty --an-upload-border-color - Dropzone border.
 * @cssproperty --an-upload-radius - Dropzone corner radius.
 * @cssproperty --an-upload-gap - Gap between the dropzone and the list.
 * @cssproperty --an-upload-font-size - Base font size.
 * @cssproperty --an-upload-focus-ring - Focus ring colour.
 * @cssproperty --an-upload-dropzone-padding - Dropzone padding.
 * @cssproperty --an-upload-dropzone-gap - Gap between trigger and hint.
 * @cssproperty --an-upload-dragover-border-color - Border colour while dragging.
 * @cssproperty --an-upload-trigger-height - Trigger button height.
 * @cssproperty --an-upload-trigger-padding-x - Trigger horizontal padding.
 * @cssproperty --an-upload-trigger-radius - Trigger corner radius.
 * @cssproperty --an-upload-trigger-bg - Trigger background.
 * @cssproperty --an-upload-trigger-fg - Trigger text colour.
 * @cssproperty --an-upload-trigger-font-size - Trigger font size.
 * @cssproperty --an-upload-hint-color - Hint and secondary text colour.
 * @cssproperty --an-upload-hint-font-size - Hint font size.
 * @cssproperty --an-upload-list-gap - Gap between list rows.
 * @cssproperty --an-upload-item-bg - List row background.
 * @cssproperty --an-upload-item-border-color - List row border.
 * @cssproperty --an-upload-item-radius - List row corner radius.
 * @cssproperty --an-upload-item-padding - List row padding.
 * @cssproperty --an-upload-item-gap - Gap inside a list row.
 * @cssproperty --an-upload-preview-size - Thumbnail edge length.
 * @cssproperty --an-upload-preview-radius - Thumbnail corner radius.
 * @cssproperty --an-upload-preview-bg - Thumbnail background.
 * @cssproperty --an-upload-name-font-size - File name font size.
 * @cssproperty --an-upload-size-color - File size colour.
 * @cssproperty --an-upload-size-font-size - File size font size.
 * @cssproperty --an-upload-progress-height - Progress bar height.
 * @cssproperty --an-upload-progress-color - Progress bar fill.
 * @cssproperty --an-upload-progress-track - Progress bar track.
 * @cssproperty --an-upload-error-color - Error text colour.
 * @cssproperty --an-upload-error-font-size - Error text size.
 * @cssproperty --an-upload-button-bg - Item button background.
 * @cssproperty --an-upload-button-color - Item button text colour.
 * @cssproperty --an-upload-button-border-color - Item button border.
 * @cssproperty --an-upload-button-radius - Item button corner radius.
 * @cssproperty --an-upload-button-font-size - Item button font size.
 * @cssproperty --an-upload-empty-color - Empty placeholder colour.
 */
export class AnUpload extends AnElement {
  static override formAssociated = true;

  static override styles = uploadStyles;

  static override defaults = {
    name: '',
    accept: '',
    multiple: false,
    maxFiles: 0,
    maxSize: 0,
    disabled: false,
    required: false,
    action: '',
    method: 'POST',
    fieldName: '',
    size: 'md' as AnUploadSize,
  };

  /** `auto-upload` is a default-true boolean, so it is handled outside `defaults`. */
  static override get observedAttributes(): string[] {
    return [...super.observedAttributes, 'auto-upload'];
  }

  declare name: string;
  declare accept: string;
  declare multiple: boolean;
  declare maxFiles: number;
  declare maxSize: number;
  declare disabled: boolean;
  declare required: boolean;
  declare action: string;
  declare method: string;
  declare fieldName: string;
  declare size: AnUploadSize;

  /** Extra request headers forwarded to the built-in XHR uploader. */
  headers: Record<string, string> = {};

  /** Custom transport; takes precedence over `action`. */
  uploader: AnUploader | undefined;

  /** Maximum number of in-flight uploads; defaults to `3`. */
  concurrency = 3;

  #items: UploadItem[] = [];
  /** Auto-start flag, default `true` and not representable via markup alone. */
  #autoUpload = true;
  /** Set while the property setter reflects itself, so the attribute does not loop. */
  #reflectingAutoUpload = false;
  /** Set by `formDisabledCallback` (e.g. a disabled ancestor `<fieldset>`). */
  #formDisabled = false;
  /** Nesting depth of `dragenter` / `dragleave`, so children cannot flicker the state. */
  #dragDepth = 0;
  /** Guards the recursive `dropzone -> input.click() -> dropzone` click path. */
  #opening = false;

  constructor() {
    super();
    // Delegation on the shadow root survives every innerHTML re-render.
    this.shadowRoot!.addEventListener('click', this.#onClick as EventListener);
    this.shadowRoot!.addEventListener('keydown', this.#onKeyDown as EventListener);
    this.shadowRoot!.addEventListener('change', this.#onChange as EventListener);
    this.shadowRoot!.addEventListener('dragenter', this.#onDragEnter as EventListener);
    this.shadowRoot!.addEventListener('dragover', this.#onDragOver as EventListener);
    this.shadowRoot!.addEventListener('dragleave', this.#onDragLeave as EventListener);
    this.shadowRoot!.addEventListener('drop', this.#onDrop as EventListener);
  }

  /** Snapshot of the queued files; mutating it never changes the queue. */
  get files(): File[] {
    return this.#items.map((item) => item.file);
  }

  /** Whether files start uploading as soon as they are accepted. */
  get autoUpload(): boolean {
    return this.#autoUpload;
  }

  set autoUpload(next: boolean) {
    const value = Boolean(next);
    if (value === this.#autoUpload) return;
    this.#autoUpload = value;
    this.#reflectingAutoUpload = true;
    try {
      this.toggleAttribute('auto-upload', value);
    } finally {
      this.#reflectingAutoUpload = false;
    }
    this.requestUpdate();
  }

  /** Platform constraint state; `undefined` when the element has no internals. */
  get validity(): ValidityState | undefined {
    return this.internals?.validity;
  }

  /** Message the owning form shows for the current constraint state. */
  get validationMessage(): string {
    return this.internals?.validationMessage ?? '';
  }

  /** Opens the native file picker; a no-op while disabled. */
  open(): void {
    if (this.#isDisabled) return;
    const input = this.#input;
    if (!input) return;
    this.#opening = true;
    try {
      input.click();
    } finally {
      this.#opening = false;
    }
  }

  /** Cancels running uploads, drops every queued file and revokes previews. */
  clear(): void {
    if (this.#items.length === 0) return;
    const removed = this.#items.map((item) => item.file);
    this.#cancelAll(true);
    this.#revokePreviews();
    this.#items = [];
    this.#syncFormValue();
    this.emit('an-upload-change', { files: [], added: [], removed } satisfies AnUploadChangeDetail);
    this.requestUpdate();
  }

  /**
   * Removes one file by index or reference; a running upload is aborted first.
   * The argument is optional only so the signature stays compatible with the
   * inherited `Element.remove()`; calling it without a file is a no-op.
   */
  override remove(fileOrIndex?: File | number): void {
    if (fileOrIndex === undefined) return;
    const index = this.#indexOf(fileOrIndex);
    if (index < 0) return;
    const [item] = this.#items.splice(index, 1);
    this.#cancel(item, true);
    this.#revokeItem(item);
    this.#syncFormValue();
    this.emit('an-upload-change', {
      files: this.files,
      added: [],
      removed: [item.file],
    } satisfies AnUploadChangeDetail);
    this.requestUpdate();
  }

  /** Starts the queue manually; requires `action` or `uploader`. */
  start(): void {
    if (this.#isDisabled || !this.#hasTransport) return;
    // Manual starts may retry files that failed; automatic ones never do.
    this.#pump(true);
  }

  /** Cancels the upload of one file; files that are not uploading are ignored. */
  abort(fileOrIndex: File | number): void {
    const index = this.#indexOf(fileOrIndex);
    if (index < 0) return;
    const item = this.#items[index];
    if (!this.#cancel(item, true)) return;
    this.requestUpdate();
    this.#pump();
  }

  /** One row per queued file, registered with the owning form. */
  protected override formEntries(): Array<[string, string | File]> {
    if (this.#isDisabled) return [];
    const name = this.fieldName || this.name;
    if (!name) return [];
    return this.#items.map((item) => [name, item.file] as [string, File]);
  }

  protected override onConnect(): void {
    // A disconnect revoked the previews; recreate them when reattached.
    let changed = false;
    for (const item of this.#items) {
      if (item.previewUrl === null) {
        item.previewUrl = this.#createPreview(item.file);
        changed = changed || item.previewUrl !== null;
      }
    }
    this.#syncFormValue();
    if (changed) this.requestUpdate();
  }

  protected override onDisconnect(): void {
    this.#dragDepth = 0;
    this.#revokePreviews();
  }

  protected override onFormReset(): void {
    this.#cancelAll(false);
    this.#revokePreviews();
    this.#items = [];
    this.#syncFormValue();
  }

  protected override onFormDisabled(disabled: boolean): void {
    if (this.#formDisabled === disabled) return;
    this.#formDisabled = disabled;
    this.#syncFormValue();
    this.requestUpdate();
  }

  override attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (name === 'auto-upload' && !this.#reflectingAutoUpload) {
      // Default-true boolean: absence keeps auto upload on, and the explicit
      // `auto-upload="false"` spelling is the declarative way to turn it off.
      this.#autoUpload = value === null ? true : value !== 'false';
    }
    super.attributeChangedCallback(name, oldValue, value);
    if (oldValue === value) return;
    if (name === 'disabled' || name === 'required' || name === 'name' || name === 'field-name') {
      this.#syncFormValue();
    }
  }

  protected render(): string {
    const disabled = this.#isDisabled;
    const accept = this.accept ? ` accept="${escapeHtml(this.accept)}"` : '';
    const multiple = this.multiple ? ' multiple' : '';
    const inputDisabled = disabled ? ' disabled' : '';
    const ariaDisabled = disabled ? ' aria-disabled="true"' : '';
    const tabindex = disabled ? '-1' : '0';
    const invalid = this.required && !disabled && this.#items.length === 0 ? ' aria-invalid="true"' : '';
    const dragover = this.#dragDepth > 0 ? ' data-dragover="true"' : '';
    const rows = this.#items.map((item, index) => this.#renderItem(item, index)).join('');
    const empty = this.#items.length === 0 ? '<p class="empty" part="empty">未选择文件</p>' : '';

    return `<div class="base" part="base">
  <div class="dropzone" part="dropzone" role="button" tabindex="${tabindex}" aria-label="选择文件"${ariaDisabled}${invalid}${dragover}>
    <slot name="trigger">
      <span class="trigger" part="trigger" aria-hidden="true">选择文件</span>
      <span class="hint">${escapeHtml(this.#hintText())}</span>
    </slot>
    <input class="input" type="file" hidden${accept}${multiple}${inputDisabled} aria-hidden="true" tabindex="-1">
  </div>
  <ul class="list" part="list">${rows}</ul>
  ${empty}
</div>`;
  }

  /** Markup of one queue row, including its buttons and progress bar. */
  #renderItem(item: UploadItem, index: number): string {
    const name = escapeHtml(item.file.name);
    const percent = item.status === 'success' ? 100 : item.percent;
    const preview = item.previewUrl ? `<img src="${escapeHtml(item.previewUrl)}" alt="">` : '';
    const error =
      item.status === 'error'
        ? `<span class="item-error" part="item-error" role="alert">${escapeHtml(item.error ?? '上传失败')}</span>`
        : item.status === 'aborted'
          ? '<span class="item-error" part="item-error" role="alert">已取消</span>'
          : '';
    const cancel =
      item.status === 'uploading'
        ? `<button type="button" class="item-cancel" part="item-cancel" data-action="cancel" data-index="${index}" aria-label="取消 ${name}">取消</button>`
        : '';

    return `<li class="item" part="item" data-index="${index}" data-status="${item.status}">
  <span class="item-preview" part="item-preview" aria-hidden="true">${preview}</span>
  <span class="item-body">
    <span class="item-head">
      <span class="item-name" part="item-name" title="${name}">${name}</span>
      <span class="item-size" part="item-size">${formatBytes(item.file.size)}</span>
    </span>
    <span class="item-progress" part="item-progress" role="progressbar" aria-label="上传进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span class="bar" style="width: ${percent}%"></span></span>
    ${error}
  </span>
  <span class="item-actions">
    ${cancel}
    <button type="button" class="item-remove" part="item-remove" data-action="remove" data-index="${index}" aria-label="移除 ${name}">移除</button>
  </span>
</li>`;
  }

  /** Hint under the default trigger, extended with the limits when set. */
  #hintText(): string {
    const parts = ['点击选择文件，或将文件拖拽到此处'];
    if (this.multiple) parts.push('可多选');
    if (this.maxSize > 0) parts.push(`单个文件不超过 ${formatBytes(this.maxSize)}`);
    return parts.join('，');
  }

  #addFiles(incoming: File[]): void {
    if (this.#isDisabled || incoming.length === 0) return;

    const accepted: File[] = [];
    for (const file of incoming) {
      if (!this.#accepts(file)) {
        this.emit('an-upload-reject', { file, reason: 'type' } satisfies AnUploadRejectDetail);
        continue;
      }
      if (this.maxSize > 0 && file.size > this.maxSize) {
        this.emit('an-upload-reject', { file, reason: 'size' } satisfies AnUploadRejectDetail);
        continue;
      }
      if (this.maxFiles > 0 && this.#items.length + accepted.length >= this.maxFiles) {
        this.emit('an-upload-reject', { file, reason: 'max-files' } satisfies AnUploadRejectDetail);
        continue;
      }
      accepted.push(file);
    }

    if (accepted.length === 0) return;

    for (const file of accepted) {
      this.#items.push({
        file,
        status: 'idle',
        loaded: 0,
        total: file.size,
        percent: 0,
        previewUrl: this.#createPreview(file),
      });
    }

    this.emit('an-upload-change', {
      files: this.files,
      added: accepted,
      removed: [],
    } satisfies AnUploadChangeDetail);
    this.#syncFormValue();
    this.requestUpdate();
    if (this.autoUpload) this.start();
  }

  /** Starts as many idle files as `concurrency` allows. */
  #pump(retry = false): void {
    if (this.#isDisabled || !this.#hasTransport) return;
    const limit = Math.max(1, Math.floor(this.concurrency) || 1);
    let active = this.#items.filter((item) => item.status === 'uploading').length;
    for (const item of this.#items) {
      if (active >= limit) break;
      if (item.status !== 'idle' && !(retry && item.status === 'error')) continue;
      active += 1;
      void this.#upload(item);
    }
  }

  /** Runs one file through the resolved transport, reporting into the queue item. */
  async #upload(item: UploadItem): Promise<void> {
    const uploader = this.#resolveUploader();
    if (!uploader) return;

    const controller = new AbortController();
    item.controller = controller;
    item.status = 'uploading';
    item.loaded = 0;
    item.total = item.file.size;
    item.percent = 0;
    item.error = undefined;
    item.response = undefined;
    this.requestUpdate();

    try {
      const response = await uploader(item.file, {
        signal: controller.signal,
        onProgress: (loaded, total) => this.#trackProgress(item, loaded, total),
      });
      if (controller.signal.aborted || item.status !== 'uploading') return;
      item.status = 'success';
      item.loaded = item.total;
      item.percent = 100;
      item.response = response;
      this.emit('an-upload-success', { file: item.file, response } satisfies AnUploadSuccessDetail);
    } catch (error) {
      // `abort()`, `remove()` and `clear()` all abort the controller first.
      if (controller.signal.aborted) return;
      item.status = 'error';
      item.error = messageOf(error);
      this.emit('an-upload-error', { file: item.file, error } satisfies AnUploadErrorDetail);
    } finally {
      if (item.controller === controller) item.controller = undefined;
      this.requestUpdate();
      this.#pump();
    }
  }

  #trackProgress(item: UploadItem, loaded: number, total: number): void {
    if (item.status !== 'uploading') return;
    const size = total > 0 ? total : item.file.size;
    item.total = size;
    item.loaded = size > 0 ? Math.max(0, Math.min(loaded, size)) : 0;
    item.percent = size > 0 ? Math.min(100, Math.round((item.loaded / size) * 100)) : 0;
    this.emit('an-upload-progress', {
      file: item.file,
      loaded: item.loaded,
      total: item.total,
      percent: item.percent,
    } satisfies AnUploadProgressDetail);
    this.requestUpdate();
  }

  /** Cancels the in-flight request of one item; returns whether one was running. */
  #cancel(item: UploadItem, notify: boolean): boolean {
    const controller = item.controller;
    if (!controller) return false;
    item.controller = undefined;
    item.status = 'aborted';
    item.error = undefined;
    controller.abort();
    if (notify) this.emit('an-upload-abort', { file: item.file } satisfies AnUploadAbortDetail);
    return true;
  }

  #cancelAll(notify: boolean): void {
    for (const item of this.#items) this.#cancel(item, notify);
  }

  /** Uploads nothing without a transport; `uploader` wins over `action`. */
  get #hasTransport(): boolean {
    return this.uploader !== undefined || this.action.length > 0;
  }

  #resolveUploader(): AnUploader | null {
    if (this.uploader) return this.uploader;
    if (!this.action) return null;
    return createXhrUploader({
      url: this.action,
      method: this.method,
      headers: this.headers,
      fieldName: this.fieldName || this.name || DEFAULT_FIELD_NAME,
    });
  }

  #syncFormValue(): void {
    const internals = this.internals;
    if (!internals) return;
    const entries = this.formEntries();
    if (entries.length === 0) {
      internals.setFormValue(null);
    } else {
      const data = new FormData();
      for (const [name, value] of entries) data.append(name, value);
      internals.setFormValue(data);
    }
    this.#syncValidity();
  }

  #syncValidity(): void {
    const internals = this.internals;
    if (!internals || typeof internals.setValidity !== 'function') return;
    const missing = this.required && !this.#isDisabled && this.#items.length === 0;
    if (missing) internals.setValidity({ valueMissing: true }, REQUIRED_MESSAGE);
    else internals.setValidity({});
  }

  /** Matches a file against `accept`: MIME, `type/*` wildcard or `.ext`. */
  #accepts(file: File): boolean {
    const tokens = parseAccept(this.accept);
    if (tokens.length === 0) return true;
    const type = (file.type || '').toLowerCase();
    const name = file.name.toLowerCase();
    return tokens.some((token) => {
      if (token === '*' || token === '*/*') return true;
      if (token.startsWith('.')) return name.endsWith(token);
      if (token.endsWith('/*')) return type.startsWith(token.slice(0, -1));
      return type === token;
    });
  }

  #createPreview(file: File): string | null {
    if (!file.type.startsWith('image/')) return null;
    if (typeof URL === 'undefined' || typeof URL.createObjectURL !== 'function') return null;
    try {
      return URL.createObjectURL(file);
    } catch {
      return null;
    }
  }

  #revokeItem(item: UploadItem): void {
    if (item.previewUrl === null) return;
    try {
      URL.revokeObjectURL(item.previewUrl);
    } catch {
      // Revoking a URL the platform already dropped is harmless.
    }
    item.previewUrl = null;
  }

  #revokePreviews(): void {
    for (const item of this.#items) this.#revokeItem(item);
  }

  #indexOf(fileOrIndex: File | number): number {
    if (typeof fileOrIndex === 'number') {
      return Number.isInteger(fileOrIndex) && fileOrIndex >= 0 && fileOrIndex < this.#items.length
        ? fileOrIndex
        : -1;
    }
    return this.#items.findIndex((item) => item.file === fileOrIndex);
  }

  /** True when the composed path of the event runs through the dropzone. */
  #inDropzone(event: Event): boolean {
    const dropzone = this.shadowRoot?.querySelector('.dropzone');
    return dropzone !== null && dropzone !== undefined && event.composedPath().includes(dropzone);
  }

  #setDragover(active: boolean): void {
    const dropzone = this.shadowRoot?.querySelector('.dropzone');
    if (!dropzone) return;
    if (active) dropzone.setAttribute('data-dragover', 'true');
    else dropzone.removeAttribute('data-dragover');
  }

  get #isDisabled(): boolean {
    return this.disabled || this.#formDisabled;
  }

  get #input(): HTMLInputElement | null {
    return this.shadowRoot?.querySelector<HTMLInputElement>('input[type="file"]') ?? null;
  }

  #onClick = (event: MouseEvent): void => {
    const target = event.composedPath()[0] as Element | null;
    const actionElement = target && 'closest' in target ? target.closest<HTMLElement>('[data-action]') : null;
    if (actionElement) {
      const index = Number(actionElement.dataset.index);
      if (actionElement.dataset.action === 'remove') this.remove(index);
      else if (actionElement.dataset.action === 'cancel') this.abort(index);
      return;
    }
    if (this.#opening) return;
    if (!this.#inDropzone(event)) return;
    if (target === this.#input) return;
    this.open();
  };

  #onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Enter' && event.key !== ' ' && event.key !== 'Spacebar') return;
    if (!this.#inDropzone(event)) return;
    const target = event.composedPath()[0] as Element | null;
    if (target === this.#input) return;
    event.preventDefault();
    this.open();
  };

  #onChange = (event: Event): void => {
    const input = event.composedPath()[0] as HTMLInputElement | null;
    if (!input || input.type !== 'file') return;
    const files = input.files ? Array.from(input.files) : [];
    // Clearing lets the same file be picked again; browsers may forbid it.
    try {
      input.value = '';
    } catch {
      // Ignore: the FileList snapshot above is already copied.
    }
    this.#addFiles(files);
  };

  #onDragEnter = (event: DragEvent): void => {
    if (!this.#inDropzone(event)) return;
    event.preventDefault();
    if (this.#isDisabled) return;
    this.#dragDepth += 1;
    this.#setDragover(true);
  };

  #onDragOver = (event: DragEvent): void => {
    if (!this.#inDropzone(event)) return;
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = this.#isDisabled ? 'none' : 'copy';
  };

  #onDragLeave = (event: DragEvent): void => {
    if (!this.#inDropzone(event)) return;
    if (this.#isDisabled) return;
    this.#dragDepth = Math.max(0, this.#dragDepth - 1);
    if (this.#dragDepth === 0) this.#setDragover(false);
  };

  #onDrop = (event: DragEvent): void => {
    if (!this.#inDropzone(event)) return;
    event.preventDefault();
    this.#dragDepth = 0;
    this.#setDragover(false);
    if (this.#isDisabled) return;
    const dropped = event.dataTransfer ? Array.from(event.dataTransfer.files) : [];
    this.#addFiles(dropped);
  };
}

